chrome.runtime.onInstalled.addListener(()=>{chrome.storage.local.set({"mindlock-state":{authorized:!1,updatedAt:Date.now()}})});chrome.runtime.onMessage.addListener(t=>{(t==null?void 0:t.type)==="set-auth-status"&&chrome.storage.local.set({"mindlock-state":{authorized:!!t.authorized,updatedAt:Date.now()}})});chrome.webRequest.onBeforeRequest.addListener(t=>t.url?{}:{},{urls:["http://*/*","https://*/*"]},["blocking"]);
